#!/bin/bash
set -uxo pipefail
echo ">>>>> Start Test Output"
cd /app/rust && bash /tests/test.sh > /tmp/verifier.log 2>&1; RC=$?; echo "===== tests/test.sh exited $RC; last 6000 bytes of its log ====="; tail -c 6000 /tmp/verifier.log; printf %s  | base64 -d > /tmp/sforge_score.py && python3 /tmp/sforge_score.py "$RC" 2>&1
EXIT_CODE=$?
echo ">>>>> End Test Output"
echo "Exit code: $EXIT_CODE"
exit 0
